    H,W=len(inp),len(inp[0]); seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=0 and not seen[r][c]:
                col=inp[r][c]; dq=deque([(r,c)]); cells=[]; seen[r][c]=True
                while dq:
                    a_,b_=dq.popleft(); cells.append((a_,b_))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a_+dr,b_+dc
                        if 0<=x<H and 0<=y<W and inp[x][y]==col and not seen[x][y]:
                            seen[x][y]=True; dq.append((x,y))
                rmin=min(p[0] for p in cells); cmin=min(p[1] for p in cells)
                h=max(p[0] for p in cells)-rmin+1; w=max(p[1] for p in cells)-cmin+1
                objs.append({'rmin':rmin,'cmin':cmin,'col':col,'cells':cells,'h':h,'w':w})
    return objs
def f(inp):
    objs=sorted(comps(inp),key=lambda o:o['rmin']+o['cmin'])
    H,W=len(inp),len(inp[0])
    out=[[0]*W for _ in range(H)]; tl=(0,0); prev=None
    for o in objs:
        if prev is None: tl=(0,0)
        else: tl=(tl[0]+prev['h']-1, tl[1]+prev['w']-1)
        for (r,c) in o['cells']:
            nr=r-o['rmin']; nc=c-o['cmin']
            rr=nr+tl[0]; cc=nc+tl[1]
            if 0<=rr<H and 0<=cc<W: out[rr][cc]=o['col']
        prev=o
    return out
